use super::*;
use crate::update_work_tests::{build,debit,debit_admission,retire};
#[test]fn actual_ranked_read_returns_original_rows_with_probe_work_and_zero_physical_copy(){let law:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&law["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};let mut fuel=s["fuel"].as_u64().unwrap();let maximum=s["maximumTurns"].as_u64().unwrap();let count=law["count"].as_u64().unwrap()as usize;let input=build(count,&mut bank,&mut fuel,maximum);let(source,p,work)=wallet::admit_source(input,bank,fuel);debit_admission(&mut bank,&mut fuel,p,work);let mut read=PersistentListRead::new();let mut actual=Vec::new();for _ in 0..maximum{let input=source.borrow();let d=read.demand(input).unwrap();for g in [RetainedCloneGrant{maximum_items:0,..bank},RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..bank}]{let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||wallet::read(&mut read,input,g).0);assert_eq!(turn.work,0);assert_eq!(turn.result.unwrap().progress(),Default::default());assert_eq!(heap,(0,0));}let((turn,row),heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||wallet::read(&mut read,input,RetainedCloneGrant{maximum_items:1,..bank}));assert_eq!(heap,(0,0));let work=turn.work;let step=turn.result.unwrap();let p=step.progress();assert_eq!(p.copied_bytes,d.copy_bytes+law["copyBytes"].as_u64().unwrap()as usize);debit(&mut bank,&mut fuel,p,work);match(step,row){(_,Some((at,row)))=>{assert!(std::ptr::eq(row.get(),input.get().get(at).unwrap()));actual.push(*row.get());},(RetainedCloneStep::Complete(_),None)=>break,_=>{}}}assert_eq!(serde_json::to_value(actual).unwrap(),serde_json::to_value((0..count as u64).collect::<Vec<_>>()).unwrap());let cached=wallet::read(&mut read,source.borrow(),Default::default()).0;assert_eq!(cached.work,0);assert!(matches!(cached.result.unwrap(),RetainedCloneStep::Complete(_)));{let turn=wallet::begin(RetainedCloneGrant{maximum_items:1,..bank},|effect|read.begin_close_paid(effect));let work=turn.work;let p=turn.result.unwrap().progress();debit(&mut bank,&mut fuel,p,work);}for _ in 0..maximum{if read.terminal_is_empty(){break}let(turn,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||crate::effect::settle(RetainedCloneGrant{maximum_items:1,..bank},|effect|wallet::poll(effect,|effect,reply|read.close_into(effect.grant().maximum_copy_bytes,effect,reply))));let p=turn.result.unwrap().progress();assert_eq!(heap,(p.retained_capacity_bytes,p.released_bytes));debit(&mut bank,&mut fuel,p,turn.work);}assert!(read.terminal_is_empty());drop(read);retire(source,&mut bank,&mut fuel,maximum);}
